typedef void (*EventCallback)(int id, void* data);

void DefaultHandler(int id, void* data) {
    /* Log event */
}

typedef struct {
    int event_id;
    EventCallback handler;
} EventHandlerRegistration;

EventHandlerRegistration listener = {
    .event_id = 0,
    .handler = DefaultHandler
};

void register_callback(EventCallback cb) {
    listener.handler = cb;
}

void trigger_event(int id, void* payload) {
    // Check for NULL pointer before invocation
    if (listener.handler) {
        listener.handler(id, payload);
    }
}
